let db; if(onlineMode) db={cars:[],customers:[],bookings:[],expenses:[],quotes:[],bankAccounts:[],company:{...defaultCompany}}; else {try{const saved=JSON.parse(localStorage.getItem(KEY))||seed();db={...saved,quotes:saved.quotes||[],bankAccounts:saved.bankAccounts||[],company:{...defaultCompany,...saved.company}};db.bookings=db.bookings.map(b=>({receiptPrintedAt:null,taxInvoicePrintedAt:null,insurance:'',insuranceCoverage:0,extraCharges:[],bankAccountId:'',...b}));db.customers=db.customers.map(c=>({taxType:'individual',line:'',taxName:'',taxId:c.license||'',taxAddress:c.address||'',province:'',district:'',subdistrict:'',postalCode:'',branch:'',...c}));db.expenses=db.expenses.map(x=>({carId:'',...x}));const ids=new Map(db.customers.map(c=>{const old=c.id;c.id=normalizePhone(c.phone)||old;c.phone=normalizePhone(c.phone)||c.phone;return[old,c.id]}));db.bookings.forEach(b=>b.customerId=ids.get(b.customerId)||b.customerId);db.quotes.forEach(q=>q.customerId=ids.get(q.customerId)||q.customerId)}catch{db={...seed(),quotes:[],bankAccounts:[],company:{...defaultCompany}}}}
