function show(view){$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#crumb').textContent={dashboard:'ภาพรวม',bookings:'รายการเช่า',fleet:'รถของเรา',customers:'ลูกค้า',finance:'บัญชีการเงิน',quotes:'ใบเสนอราคา',company:'ข้อมูลบริษัท',banks:'บัญชีธนาคาร'}[view];window.scrollTo(0,0)}
function render(){renderDashboard();renderBookings();renderFleet();renderCustomers();renderFinance();renderQuotes();$('#booking-count').textContent=db.bookings.filter(b=>!['completed','cancelled'].includes(b.status)).length;const free=availableCarsToday();$('#stat-available').textContent=free.length;$('#fleet-progress').style.width=(db.cars.length?free.length/db.cars.length*100:0)+'%';renderAvailableToday();const list=db.cars.filter(c=>carFilter==='all'||(carFilter==='available'?c.available:!c.available));$$('#car-grid .car-card').forEach((card,i)=>{const c=list[i];if(c?.image){const holder=card.querySelector('.car-visual span');if(holder)holder.innerHTML=`<img src="${esc(c.image)}" alt="${esc(c.name)}">`}})}
function renderDashboard(){const month=String(new Date().getMonth()+1).padStart(2,'0'),year=new Date().getFullYear();const monthBookings=db.bookings.filter(b=>b.created?.startsWith(`${year}-${month}`)&&b.paid&&b.status!=='cancelled');$('#stat-revenue').textContent=money(monthBookings.reduce((a,b)=>a+b.total,0));$('#stat-fleet').textContent=db.cars.length;const available=db.cars.filter(c=>c.available&& !db.bookings.some(b=>b.carId===c.id&&['confirmed','ongoing'].includes(b.status)&&new Date(b.start)<new Date()&&new Date(b.end)>new Date())).length;$('#stat-available').textContent=available;$('#fleet-progress').style.width=(db.cars.length?available/db.cars.length*100:0)+'%';$('#stat-bookings').textContent=db.bookings.length;$('#stat-active').textContent=db.bookings.filter(b=>b.status==='ongoing').length;$('#stat-customers').textContent=db.customers.length;$('#today').textContent=new Date().toLocaleDateString('th-TH',{weekday:'short',day:'numeric',month:'short',year:'numeric'});renderCalendar();renderDayList(selectedDay);$('#recent-table').innerHTML=db.bookings.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,5).map(bookingRow).join('')||'<tr><td colspan="7" class="empty-state">ยังไม่มีรายการเช่า</td></tr>'}
function renderCalendar(){const year=calDate.getFullYear(),month=calDate.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate();$('#month-label').textContent=calDate.toLocaleDateString('th-TH',{month:'long',year:'numeric'});const weekdays=['จ','อ','พ','พฤ','ศ','ส','อา'];let html=weekdays.map(d=>`<div class="weekday">${d}</div>`).join('');for(let i=0;i<42;i++){let num,date,muted=false;if(i<offset){num=prevDays-offset+i+1;date=new Date(year,month-1,num);muted=true}else if(i>=offset+days){num=i-offset-days+1;date=new Date(year,month+1,num);muted=true}else{num=i-offset+1;date=new Date(year,month,num)}let iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,count=db.bookings.filter(b=>b.status!=='cancelled'&&b.start.slice(0,10)<=iso&&b.end.slice(0,10)>=iso).length;html+=`<div class="day-cell ${muted?'muted':''} ${iso===todayISO()?'current':''} ${iso===selectedDay?'selected':''}" data-day="${iso}"><span class="day-number">${num}</span>${count?`<span class="day-marker">${count>2?'<em></em><em></em><em></em>':Array.from({length:count},()=>'<em></em>').join('')}</span>`:''}</div>`}$('#calendar').innerHTML=html;$$('.day-cell').forEach(el=>el.onclick=()=>{selectedDay=el.dataset.day;renderCalendar();renderDayList(selectedDay)})}
function renderDayList(day){$('#schedule-title').textContent=day===todayISO()?'รายการวันนี้':`รายการ ${dateFmt(day)}`;const list=db.bookings.filter(b=>b.status!=='cancelled'&&b.start.slice(0,10)<=day&&b.end.slice(0,10)>=day).sort((a,b)=>a.start.localeCompare(b.start));$('#today-list').innerHTML=list.length?list.slice(0,5).map(b=>{const c=customer(b.customerId),v=car(b.carId),pickup=b.start.slice(0,10)===day,returned=b.end.slice(0,10)===day,when=[pickup?`รับ ${timeFmt(b.start)}`:'',returned?`คืน ${timeFmt(b.end)}`:''].filter(Boolean).join(' · ')||'อยู่ระหว่างเช่า';return `<div class="schedule-item"><div class="schedule-time">${pickup?timeFmt(b.start):returned?timeFmt(b.end):'—'}</div><div class="schedule-detail"><b>${esc(v?.name||'รถถูกลบ')} · ${esc(c?.name||'')}</b><small>${esc(v?.plate||'')} · ${when} · ${statusLabel[b.status]}</small></div></div>`}).join(''):'<div class="empty-small">ไม่มีรายการรถในวันที่เลือก</div>'}
function bookingRow(b,showDocs=false){const c=customer(b.customerId),v=car(b.carId),docCell=showDocs?`<div class="doc-actions"><button class="text-button" data-doc="receipt" data-doc-booking="${b.id}">ใบเสร็จ</button><small class="print-state ${b.receiptPrintedAt?'printed':'pending'}">${b.receiptPrintedAt?'พิมพ์แล้ว':'ยังไม่พิมพ์'}</small><button class="text-button" data-doc="invoice" data-doc-booking="${b.id}">ใบกำกับภาษี</button><small class="print-state ${b.taxInvoicePrintedAt?'printed':'pending'}">${b.taxInvoicePrintedAt?'พิมพ์แล้ว':'ยังไม่พิมพ์'}</small></div>`:'';return `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc((c?.name||'?').replace('คุณ','').slice(0,1))}</span><div><b>${esc(c?.name||'ไม่พบข้อมูลลูกค้า')}</b><span class="subtext">${b.id}</span></div></div></td><td>${esc(v?.name||'รถถูกลบ')}<span class="subtext">${esc(v?.plate||'')}</span></td><td>${dtFmt(b.start)}</td><td>${dtFmt(b.end)}</td><td>${b.days} วัน</td><td><b>${money(b.total)}</b>${b.paid?'<span class="subtext">ชำระแล้ว</span>':'<span class="subtext">รอชำระ</span>'}</td><td><span class="status status-${b.status}">${statusLabel[b.status]||b.status}</span></td>${showDocs?`<td>${docCell}</td>`:''}<td><button class="row-action" data-booking="${b.id}" title="จัดการ">⋯</button></td></tr>`}
function renderBookings(){const term=($('#booking-search')?.value||'').toLowerCase(),filter=$('#booking-filter')?.value||'all';let rows=db.bookings.filter(b=>{const c=customer(b.customerId),v=car(b.carId);return(filter==='all'||b.status===filter)&&`${c?.name} ${v?.name} ${v?.plate} ${b.id}`.toLowerCase().includes(term)}).sort((a,b)=>b.created.localeCompare(a.created));$('#bookings-table').innerHTML=rows.map(b=>bookingRow(b,true)).join('');$('#bookings-empty').classList.toggle('hidden',rows.length>0);$$('[data-booking]').forEach(el=>el.onclick=()=>bookingActions(el.dataset.booking));$$('[data-doc-booking]').forEach(el=>el.onclick=()=>printBookingDocument(el.dataset.docBooking,el.dataset.doc))}
function renderFleet(){const list=db.cars.filter(c=>carFilter==='all'||(carFilter==='available'?c.available:!c.available));$('#fleet-caption').textContent=`แสดง ${list.length} จาก ${db.cars.length} คัน`;$('#car-grid').innerHTML=list.map(c=>`<article class="car-card"><div class="car-visual"><span>${esc(c.icon||'🚘')}</span><label class="car-status ${c.available?'':'off'}">${c.available?'พร้อมให้เช่า':'ไม่พร้อมให้เช่า'}</label></div><div class="car-info"><h3>${esc(c.name)}</h3><div class="plate">${esc(c.plate)}</div><div class="car-specs"><span>♙ ${c.seats} ที่นั่ง</span><span>⚙ ${esc(c.transmission)}</span><span>⛽ ${esc(c.fuel)}</span></div><div class="car-price"><span>ราคาเช่าต่อวัน</span><b>${money(c.price)}</b></div><div class="car-card-actions" style="margin-top:10px"><button data-edit-car="${c.id}">แก้ไขข้อมูล</button><button data-toggle-car="${c.id}">${c.available?'ปิดให้เช่า':'เปิดให้เช่า'}</button><button class="danger" data-delete-car="${c.id}">ลบ</button></div></div></article>`).join('')||'<div class="empty-state">ไม่พบรถในหมวดนี้</div>';$$('[data-edit-car]').forEach(x=>x.onclick=()=>carForm(x.dataset.editCar));$$('[data-toggle-car]').forEach(x=>x.onclick=()=>{let c=car(x.dataset.toggleCar);c.available=!c.available;persist();toast('อัปเดตสถานะรถแล้ว')});$$('[data-delete-car]').forEach(x=>x.onclick=()=>deleteCar(x.dataset.deleteCar))}
function renderCustomers(){const term=($('#customer-search')?.value||'').toLowerCase(),rows=db.customers.filter(c=>`${c.name} ${c.phone} ${c.license} ${c.taxId} ${c.line}`.toLowerCase().includes(term));$('#customers-table').innerHTML=rows.map(c=>{const bs=db.bookings.filter(b=>b.customerId===c.id&&b.status!=='cancelled');return `<tr><td><div class="customer-cell"><span class="customer-avatar">${esc(c.name.replace('คุณ','').slice(0,1))}</span><div><b>${esc(c.name)}</b><span class="subtext">${esc(c.taxName||c.address||'')}</span></div></div></td><td>${esc(c.phone)}<span class="subtext">LINE: ${esc(c.line||'—')}</span></td><td>${esc(c.email||'—')}</td><td>${esc(c.taxId||c.license||'—')}<span class="subtext">${c.taxType==='company'?'นิติบุคคล':'บุคคลธรรมดา'}</span></td><td>${bs.length}</td><td><b>${money(bs.reduce((s,b)=>s+b.total,0))}</b></td><td><button class="row-action" data-edit-customer="${c.id}">⋯</button></td></tr>`}).join('');$('#customers-empty').classList.toggle('hidden',rows.length>0);$$('[data-edit-customer]').forEach(x=>x.onclick=()=>customerActions(x.dataset.editCustomer))}
function renderFinance(){const income=db.bookings.filter(b=>b.paid&&b.status!=='cancelled').reduce((s,b)=>s+b.total,0),expenses=db.expenses.reduce((s,e)=>s+Number(e.amount),0),pending=db.bookings.filter(b=>!b.paid&&b.status!=='cancelled').reduce((s,b)=>s+b.total,0);$('#fin-income').textContent=money(income);$('#fin-expenses').textContent=money(expenses);$('#fin-net').textContent=money(income-expenses);$('#fin-pending').textContent=money(pending);let entries=[...db.bookings.filter(b=>b.status!=='cancelled').map(b=>({date:b.created,title:`ค่าเช่ารถ ${car(b.carId)?.name||''}`,category:'รายได้ค่าเช่า',ref:b.id,payment:b.payment+(b.bankAccountId?' · '+(db.bankAccounts.find(a=>a.id===b.bankAccountId)?.nickname||'') : ''),amount:b.paid?b.total:0,pending:!b.paid})),...db.expenses.map(e=>({date:e.date,title:`${e.title}${e.carId?' · '+(car(e.carId)?.name||'รถ'):' · ไม่ระบุรถ'}`,category:e.category,ref:e.id,payment:e.payment,amount:-Number(e.amount)}))].sort((a,b)=>b.date.localeCompare(a.date));const filter=$('#ledger-filter')?.value||'all';if(filter==='income')entries=entries.filter(e=>e.amount>=0&&!e.pending);if(filter==='expense')entries=entries.filter(e=>e.amount<0);$('#ledger-table').innerHTML=entries.map(e=>`<tr><td>${dateFmt(e.date)}</td><td>${esc(e.title)}${e.pending?'<span class="subtext">รอชำระ</span>':''}</td><td>${esc(e.category)}</td><td>${e.ref}</td><td>${esc(e.payment||'—')}</td><td class="${e.amount<0?'ledger-minus':'ledger-plus'}"><b>${e.amount<0?'−':'+'}${money(Math.abs(e.amount))}</b></td></tr>`).join('');$('#ledger-empty').classList.toggle('hidden',entries.length>0)}
function openModal(title,subtitle,content){const backdrop=$('#modal-backdrop'),modal=$('#modal');if(!backdrop||!modal){console.error('AB CARRENT: modal container is missing');return null}modal.innerHTML=`<header class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><button type="button" class="close-modal" aria-label="ปิดหน้าต่าง">×</button></header><div class="modal-content">${content}</div>`;modal.classList.add('wide');backdrop.onclick=null;backdrop.classList.remove('hidden');modal.querySelector('.close-modal').onclick=closeModal;return modal}
