async function requireSupabaseResult(query){const {data,error}=await query;if(error)throw error;return data}
async function uploadCarPhoto(carRecord){if(!carRecord.image?.startsWith('data:'))return;const blob=await (await fetch(carRecord.image)).blob(),path=`${carRecord.id}/${Date.now()}-${Math.random().toString(36).slice(2)}.jpg`;const {error}=await supabaseClient.storage.from('car-photos').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;carRecord.image=supabaseClient.storage.from('car-photos').getPublicUrl(path).data.publicUrl}
async function uploadCustomerDocuments(c){for(const key of ['idDocument','licenseDocument']){const data=c[key+'Data'];if(!data?.startsWith('data:'))continue;const blob=await(await fetch(data)).blob(),path=`${normalizePhone(c.phone)}/${key}-${Date.now()}-${Math.random().toString(36).slice(2)}.pdf`,{error}=await supabaseClient.storage.from('customer-documents').upload(path,blob,{contentType:'application/pdf',upsert:false});if(error)throw error;c[key+'Path']=path;c[key+'Data']=''}}
async function moveCustomerDocumentsToPhoneFolders(){if(!onlineMode)return;const moved=[];for(const c of db.customers){const folder=normalizePhone(c.phone);if(!folder)continue;for(const key of ['idDocument','licenseDocument']){const path=c[key+'Path'];if(!path||path.startsWith(`${folder}/`))continue;const {data:signed,error}=await supabaseClient.storage.from('customer-documents').createSignedUrl(path,60);if(error)throw error;const response=await fetch(signed.signedUrl);if(!response.ok)throw new Error('ดาวน์โหลดเอกสารเดิมไม่สำเร็จ');const blob=await response.blob(),next=`${folder}/${key}-${Date.now()}-${Math.random().toString(36).slice(2)}.pdf`,{error:uploadError}=await supabaseClient.storage.from('customer-documents').upload(next,blob,{contentType:'application/pdf',upsert:false});if(uploadError)throw uploadError;c[key+'Path']=next;moved.push({id:c.id,key,next,path})}}if(moved.length){await persist();const safe=moved.filter(x=>customer(x.id)?.[x.key+'Path']===x.next).map(x=>x.path);if(safe.length)await supabaseClient.storage.from('customer-documents').remove(safe)}}
const quoteFromDb=r=>({id:r.id,customerId:r.customer_id,carId:r.car_id,start:localDateTime(r.pickup_at),end:localDateTime(r.return_at),days:r.rental_days,total:Number(r.total),deposit:Number(r.deposit),insurance:r.insurance_name||'',insuranceCoverage:Number(r.insurance_coverage)||0,extraCharges:r.extra_charges||[],status:r.status,created:localDateStamp(r.created_at)});
const quoteToDb=q=>({id:q.id,customer_id:q.customerId,car_id:q.carId,pickup_at:new Date(q.start).toISOString(),return_at:new Date(q.end).toISOString(),rental_days:q.days,daily_rate_snapshot:car(q.carId)?.price||0,total:q.total,deposit:q.deposit||0,insurance_name:q.insurance||null,insurance_coverage:q.insuranceCoverage||0,extra_charges:q.extraCharges||[],status:q.status,created_at:new Date(`${q.created||todayISO()}T12:00`).toISOString()});
async function syncRemoteState(){if(!syncedState)return;const target=deepCopy(db),specs=[{key:'cars',table:'cars',to:carToDb},{key:'customers',table:'customers',to:customerToDb},{key:'bankAccounts',table:'bank_accounts',to:bankAccountToDb},{key:'bookings',table:'bookings',to:bookingToDb},{key:'expenses',table:'expenses',to:expenseToDb},{key:'quotes',table:'quotes',to:quoteToDb}];for(const spec of specs){const before=new Map((syncedState[spec.key]||[]).map(x=>[x.id,JSON.stringify(x)])),changed=target[spec.key].filter(x=>before.get(x.id)!==JSON.stringify(x));if(spec.key==='cars')for(const c of changed)await uploadCarPhoto(c);if(spec.key==='customers')for(const c of changed)await uploadCustomerDocuments(c);if(changed.length)await requireSupabaseResult(supabaseClient.from(spec.table).upsert(changed.map(spec.to)));}if(JSON.stringify(target.company)!==JSON.stringify(syncedState.company))await requireSupabaseResult(supabaseClient.from('company_settings').upsert({id:'default',profile:target.company}));for(const spec of [...specs].reverse()){const now=new Set(target[spec.key].map(x=>x.id)),deleted=(syncedState[spec.key]||[]).filter(x=>!now.has(x.id)).map(x=>x.id);if(deleted.length)await requireSupabaseResult(supabaseClient.from(spec.table).delete().in('id',deleted));}for(const c of target.customers){const live=customer(c.id);if(live){for(const key of ['idDocument','licenseDocument'])if(live[key+'Data']&&c[key+'Path'])live[key+'Data']=''}}for(const savedCar of target.cars){const liveCar=car(savedCar.id);if(liveCar&&liveCar.image?.startsWith('data:')&&savedCar.image!==liveCar.image)liveCar.image=savedCar.image}syncedState=deepCopy(target)}
function persist(){if(!onlineMode){persistLocal();return}render();remoteSaveQueue=remoteSaveQueue.then(syncRemoteState).catch(error=>{const message=error?.code==='23P01'?'รถคันนี้ถูกจองทับช่วงเวลาโดยรายการอื่นแล้ว':(error?.message||'บันทึกฐานข้อมูลไม่สำเร็จ');db=deepCopy(syncedState||db);render();toast(message);console.error('AB CARRENT Supabase save:',error)});return remoteSaveQueue}
function showLogin(message=''){const screen=$('#auth-screen');screen.classList.remove('hidden');$('.sidebar').classList.add('hidden');$('.main').classList.add('hidden');$('#auth-error').textContent=message;$('#logout-button').classList.add('hidden')}
async function startRemoteSession(user){try{const admin=await requireSupabaseResult(supabaseClient.from('ab_admins').select('user_id,display_name').eq('user_id',user.id).maybeSingle());if(!admin){await supabaseClient.auth.signOut();showLogin('บัญชีนี้ยังไม่ได้รับสิทธิ์ผู้ดูแลระบบ');return}activeAdmin=admin;const [cars,customers,bookings,expenses,quotes,bankAccounts,companyResult]=await Promise.all([requireSupabaseResult(supabaseClient.from('cars').select('*').order('name')),requireSupabaseResult(supabaseClient.from('customers').select('*').order('name')),requireSupabaseResult(supabaseClient.from('bookings').select('*').order('created_at',{ascending:false})),requireSupabaseResult(supabaseClient.from('expenses').select('*').order('expense_date',{ascending:false})),requireSupabaseResult(supabaseClient.from('quotes').select('*').order('created_at',{ascending:false})),requireSupabaseResult(supabaseClient.from('bank_accounts').select('*').order('nickname')),requireSupabaseResult(supabaseClient.from('company_settings').select('profile').eq('id','default').maybeSingle())]);db={cars:cars.map(carFromDb),customers:customers.map(customerFromDb),bookings:bookings.map(bookingFromDb),expenses:expenses.map(expenseFromDb),quotes:quotes.map(quoteFromDb),bankAccounts:bankAccounts.map(bankAccountFromDb),company:{...defaultCompany,...(companyResult?.profile||{})}};syncedState=deepCopy(db);$('#auth-screen').classList.add('hidden');$('.sidebar').classList.remove('hidden');$('.main').classList.remove('hidden');$('#logout-button').classList.remove('hidden');$('#profile-name').textContent=admin.display_name||user.email||'ผู้ดูแลระบบ';$('#storage-mode').textContent='ข้อมูลซิงก์ผ่าน Supabase';render();setTimeout(()=>moveCustomerDocumentsToPhoneFolders().catch(error=>{console.error('AB CARRENT customer file migration:',error);toast('ย้ายเอกสาร PDF ไปโฟลเดอร์ตามเบอร์โทรไม่สำเร็จ')}),0)}catch(error){console.error('AB CARRENT Supabase load:',error);showLogin('เชื่อมฐานข้อมูลไม่สำเร็จ กรุณารัน migration ล่าสุดและตรวจสอบ RLS')}}
async function initializeApp(){if(supabaseConfigured&&!onlineMode){showLogin('โหลด Supabase client ไม่สำเร็จ กรุณารีเฟรชหน้าเว็บเมื่อเชื่อมต่ออินเทอร์เน็ต');return}if(!onlineMode){render();return}$('#login-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));$('#auth-error').textContent='กำลังเข้าสู่ระบบ…';const {data:result,error}=await supabaseClient.auth.signInWithPassword({email:data.email,password:data.password});if(error){$('#auth-error').textContent='อีเมลหรือรหัสผ่านไม่ถูกต้อง หรือยังตั้งค่าฐานข้อมูลไม่ครบ';return}await startRemoteSession(result.user)};$('#logout-button').onclick=async()=>{await supabaseClient.auth.signOut();showLogin()};const {data,error}=await supabaseClient.auth.getSession();if(error){showLogin('เชื่อมต่อ Supabase ไม่สำเร็จ');return}if(data.session)await startRemoteSession(data.session.user);else showLogin()}
function deleteCar(id){if(db.bookings.some(b=>b.carId===id))return toast('ลบรถไม่ได้ เพราะมีประวัติรายการเช่าอยู่');if(confirm('ยืนยันการลบรถคันนี้?')){db.cars=db.cars.filter(c=>c.id!==id);persist();toast('ลบรถออกจากระบบแล้ว')}}
