$$('.nav-item').forEach(x=>x.onclick=()=>show(x.dataset.view));$$('[data-goto]').forEach(x=>x.onclick=()=>show(x.dataset.goto));$('#new-booking').onclick=()=>bookingForm();$('#new-quote').onclick=quoteForm;$('#add-car').onclick=()=>carForm();$('#add-customer').onclick=()=>customerForm();$('#add-expense').onclick=expenseForm;$('#edit-company').onclick=companyForm;$('#add-bank-account').onclick=()=>bankAccountForm();$('#print-customers').onclick=printCustomers;$('#prev-month').onclick=()=>{calDate.setMonth(calDate.getMonth()-1);renderCalendar()};$('#next-month').onclick=()=>{calDate.setMonth(calDate.getMonth()+1);renderCalendar()};$('#this-month').onclick=()=>{calDate=new Date();selectedDay=todayISO();renderCalendar();renderDayList(selectedDay)};$('#booking-search').oninput=renderBookings;$('#booking-filter').onchange=renderBookings;$('#customer-search').oninput=renderCustomers;$('#ledger-filter').onchange=renderFinance;$$('[data-car-filter]').forEach(x=>x.onclick=()=>{carFilter=x.dataset.carFilter;$$('[data-car-filter]').forEach(b=>b.classList.toggle('active',b===x));renderFleet()});$('#export-csv').onclick=exportCSV;
